CREATE TABLE akun (id INTEGER PRIMARY KEY, nama TEXT NOT NULL, jenis TEXT NOT NULL, saldo INTEGER NOT NULL CHECK (saldo >= 0), CONSTRAINT batas_saldo_warung CHECK (jenis <> 'warung' OR saldo <= 1500000));
CREATE TABLE topup (id INTEGER PRIMARY KEY, akun_id INTEGER NOT NULL REFERENCES akun (id), nominal INTEGER NOT NULL CHECK (nominal > 0));
CREATE TABLE transaksi (id INTEGER PRIMARY KEY, dari INTEGER NOT NULL REFERENCES akun (id), ke INTEGER NOT NULL REFERENCES akun (id), jumlah INTEGER NOT NULL CHECK (jumlah > 0));
CREATE TABLE koreksi (id INTEGER PRIMARY KEY, akun_id INTEGER NOT NULL REFERENCES akun (id), jumlah INTEGER NOT NULL, alasan TEXT NOT NULL);
-- 29 karyawan lain digabung jadi satu akun, dan pembayaran mereka ke Warung Ani jadi satu baris
INSERT INTO akun VALUES (1, '29 karyawan lain', 'karyawan', 0), (418, 'Warung Ani', 'warung', 1450000), (419, 'Budi', 'karyawan', 250000);
INSERT INTO topup (akun_id, nominal) VALUES (1, 1450000), (419, 250000);
INSERT INTO transaksi (dari, ke, jumlah) VALUES (1, 418, 1450000);
-- Catatan Budi tersebar di tiga tabel dengan bentuk berbeda
CREATE VIEW catatan_budi AS
  SELECT 'topup' AS catatan, nominal AS jumlah FROM topup WHERE akun_id = 419
  UNION ALL SELECT 'transaksi ke ' || (SELECT nama FROM akun WHERE id = t.ke), -t.jumlah FROM transaksi t WHERE t.dari = 419
  UNION ALL SELECT 'transaksi dari ' || (SELECT nama FROM akun WHERE id = t.dari), t.jumlah FROM transaksi t WHERE t.ke = 419
  UNION ALL SELECT 'koreksi', jumlah FROM koreksi WHERE akun_id = 419;
CREATE VIEW pertanyaan_pak_hadi AS
  SELECT 1 AS urut, 'baris catatan Budi' AS pertanyaan, (SELECT group_concat(catatan || ' ' || printf('%+d', jumlah), '; ') FROM catatan_budi) AS jawaban_database
  UNION ALL SELECT 2, 'jumlah catatan Budi', (SELECT coalesce(sum(jumlah), 0) FROM catatan_budi)
  UNION ALL SELECT 3, 'saldo Budi di app', (SELECT saldo FROM akun WHERE id = 419)
  UNION ALL SELECT 4, 'selisih seluruh sistem (harus 0)', (SELECT sum(saldo) FROM akun) - (SELECT sum(nominal) FROM topup);

