CREATE TABLE buku (id INTEGER PRIMARY KEY, nama TEXT NOT NULL, jenis TEXT NOT NULL);
CREATE TABLE jurnal (id INTEGER PRIMARY KEY, jenis TEXT NOT NULL, keterangan TEXT NOT NULL);
CREATE TABLE posting (id INTEGER PRIMARY KEY, jurnal_id INTEGER NOT NULL REFERENCES jurnal (id), buku_id INTEGER NOT NULL REFERENCES buku (id), jumlah INTEGER NOT NULL CHECK (jumlah <> 0));
-- Hanya di widget ini: batas saldo warung Rp1.500.000 sebagai trigger, supaya After gagal di titik yang sama dengan Before.
-- Di lab Tahap 2, buku.batas_saldo dibaca service Bayar di dalam transaction dan belum dijaga database (labs/b3-ledger/schema.sql).
CREATE TRIGGER batas_saldo_warung BEFORE INSERT ON posting
  WHEN (SELECT jenis FROM buku WHERE id = NEW.buku_id) = 'warung'
   AND (SELECT coalesce(sum(jumlah), 0) FROM posting WHERE buku_id = NEW.buku_id) + NEW.jumlah > 1500000
  BEGIN SELECT RAISE(ABORT, 'batas_saldo_warung'); END;
INSERT INTO buku VALUES (1, 'tunjangan', 'tunjangan'), (2, '29 karyawan lain', 'karyawan'), (418, 'Warung Ani', 'warung'), (419, 'Budi', 'karyawan');
INSERT INTO jurnal VALUES (1, 'topup', 'Tunjangan 29 karyawan lain'), (2, 'topup', 'Tunjangan Budi'), (3, 'bayar', 'Pembayaran 29 karyawan lain ke Warung Ani');
INSERT INTO posting (jurnal_id, buku_id, jumlah) VALUES (1, 1, -1450000), (1, 2, 1450000), (2, 1, -250000), (2, 419, 250000), (3, 2, -1450000), (3, 418, 1450000);
-- Catatan Budi adalah posting buku Budi, satu bentuk untuk semua kejadian
CREATE VIEW catatan_budi AS
  SELECT 'jurnal ' || j.id || ' ' || j.jenis AS catatan, p.jumlah FROM posting p JOIN jurnal j ON j.id = p.jurnal_id WHERE p.buku_id = 419;
CREATE VIEW pertanyaan_pak_hadi AS
  SELECT 1 AS urut, 'baris catatan Budi' AS pertanyaan, (SELECT group_concat(catatan || ' ' || printf('%+d', jumlah), '; ') FROM catatan_budi) AS jawaban_database
  UNION ALL SELECT 2, 'jumlah catatan Budi', (SELECT coalesce(sum(jumlah), 0) FROM catatan_budi)
  UNION ALL SELECT 3, 'saldo Budi di app', (SELECT coalesce(sum(jumlah), 0) FROM posting WHERE buku_id = 419)
  UNION ALL SELECT 4, 'selisih seluruh sistem (harus 0)', (SELECT sum(jumlah) FROM posting);
